#!/usr/bin/env python3
"""Freeze CPython 3.12's Unicode data for the scoped SEARCH reference."""
import json, sys, unicodedata as u
from pathlib import Path
if sys.version_info[:2] != (3,12) or u.unidata_version != '15.0.0':
    raise SystemExit('requires CPython 3.12 and Unicode 15.0.0')
# Ranges encode Python Unicode predicates. Mapping values are NFD after lowercase.
def ranges(pred):
    out=[]; start=None
    for cp in range(0x110000):
        if pred(chr(cp)):
            if start is None: start=cp
        elif start is not None:
            out.append([start,cp-1]); start=None
    if start is not None: out.append([start,0x10ffff])
    return out
lower={}; combining={}
for cp in range(0x110000):
    ch=chr(cp); value=u.normalize('NFD',ch.lower())
    if ch != value: lower[cp]=value
    cls=u.combining(ch)
    if cls: combining[cp]=cls
cased=lambda ch: (ch+'Σ').lower().endswith('ς')
ignorable=lambda ch: ('AΣ'+ch+'!').lower()[1] == 'ς' and ('AΣ'+ch+'A').lower()[1] == 'σ'
data={'version':u.unidata_version,'lower':lower,'combining':combining,'letterNumber':ranges(lambda c:u.category(c)[0] in 'LN'),'decimal':ranges(lambda c:u.category(c)=='Nd'),'space':ranges(str.isspace),'printable':ranges(str.isprintable),'cased':ranges(cased),'caseIgnorable':ranges(ignorable)}
target=Path(__file__).resolve().parents[3]/'src/validate/search-unicode-data.ts'
content='// Generated by fixtures/wave17c/generate_unicode.py with CPython 3.12 / Unicode 15.0.0.\n// prettier-ignore\nexport const unicodeData: UnicodeData = '+json.dumps(data,ensure_ascii=True,separators=(',',':'))+';\nexport interface UnicodeData {\n  version: string;\n  lower: Record<string, string>;\n  combining: Record<string, number>;\n  letterNumber: number[][];\n  decimal: number[][];\n  space: number[][];\n  printable: number[][];\n  cased: number[][];\n  caseIgnorable: number[][];\n}\n'
if '--check' in sys.argv:
 if target.read_text()!=content: raise SystemExit('Unicode tables differ')
else: target.write_text(content)
print('Unicode '+u.unidata_version+' tables, '+str(len(content))+' bytes')
